protected boolean isValidMultibuy()
{
    boolean ret = next isValidMultibuy();

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        ret =  ret || this.MultibuyDiscountType == RetailDiscountTypeEnum::UnitPriceDiscAmt;
    }

    return ret;
}
